    """G5 data backfill.

    1. Bridge: existing "custom" shim BotSubscriptionPlans were created with
       name=SubscriptionPlan.name (SubscribeView / _ensure_bot_plan), so a
       name match links them to their Model C tier. This is what makes the
       referral commission tier ladder walkable for pre-G5 subscriptions.
    2. Commission tier: the creator plan earns commissions (FR A7 baseline;
       admins can toggle any tier afterwards — no code constants).
    """
    SubscriptionPlan = apps.get_model("payments", "SubscriptionPlan")
    BotSubscriptionPlan = apps.get_model("payments", "BotSubscriptionPlan")

    for plan in SubscriptionPlan.objects.all():
        BotSubscriptionPlan.objects.filter(
            name=plan.name,
            bot_type="custom",
            subscription_plan__isnull=True,
        ).update(subscription_plan=plan)

    SubscriptionPlan.objects.filter(slug="creator").update(grants_referral_commission=True)


